232	// ── Public API ────────────────────────────────────────────────────────────────
233	
234	/**
235	 * Iterate poll results where `merged === true` and close out each task:
236	 * mark done, activate unblocked dependents, and merge the workspace PR.
237	 */
238	export async function handleMergedPrs(opts: HandleMergedPrsOptions): Promise<void> {
239	  const {
240	    prResults,
241	    workspaceRoot,
242	    mgmtRepoOwner,
243	    mgmtRepoName,
244	    mgmtBaseBranch = "main",
245	    githubToken,
246	    gitAuthorEmail,
247	    gitAuthorName,
248	    sshKeyPath,
249	    emit,
250	  } = opts;
251	
252	  const mergedResults = prResults.filter((r) => r.merged === true);
253	  if (mergedResults.length === 0) return;
254	
255	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
256	  const invoker = opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
257	
258	  for (const result of mergedResults) {
259	    const { taskId, featureId } = result;
260	    const taskBranch = taskBranchName(featureId, taskId);
261	    const relPath = taskYamlRelPath(featureId, taskId);
262	
263	    // ── 1. Idempotency guard: read live task state from feature branch ─────────
264	    const liveTask = tryReadTaskFromBranch(workspaceRoot, taskBranch, relPath);
265	    if (!liveTask) {
266	      emit({
267	        type: "pr_merge_skip",
268	        task_id: taskId,
269	        feature_id: featureId,
270	        reason: "task_branch_not_found",
271	      });
272	      continue;
273	    }
274	
275	    if (liveTask.status !== "in_review") {
276	      // Fast-path: task is already done but workspace PR is still open — skip YAML
277	      // updates and go straight to the rebase + merge. This handles the case where
278	      // the executor wrote "done" directly (bypassing the orchestrator's normal flow)
279	      // while workspace_pr.url is still set and the management-repo PR is still open.
280	      if (
281	        liveTask.status === "done" &&
282	        liveTask.workspace_pr?.url &&
283	        liveTask.workspace_pr.status !== "merged"
284	      ) {
285	        emit({
286	          type: "workspace_pr_pending_for_done_task",
287	          task_id: taskId,
288	          feature_id: featureId,
289	          workspace_pr_url: liveTask.workspace_pr.url,
290	        });
291	
292	        // Rebase + push the feature branch, then merge the workspace PR.
293	        try {
294	          execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
295	          execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
296	        } catch (e) {
297	          emit({
298	            type: "workspace_pr_merge_failed",
299	            task_id: taskId,
300	            feature_id: featureId,
301	            reason: "branch_checkout_failed",
302	            details: String(e),
303	          });
304	          continue;
305	        }
306	
307	        const fastRebase = spawnSync(
308	          "git",
309	          ["-C", workspaceRoot, "rebase", `origin/${mgmtBaseBranch}`],
310	          { env, encoding: "utf-8" },
311	        );
312	
313	        if (fastRebase.status !== 0) {
314	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
315	          emit({
316	            type: "workspace_pr_merge_failed",
317	            task_id: taskId,
318	            feature_id: featureId,
319	            reason: "rebase_failed_for_done_task",
320	            details: fastRebase.stderr ?? "",
321	          });
322	          continue;
323	        }
324	
325	        const fastPush = spawnSync(
326	          "git",
327	          ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
328	          { env, encoding: "utf-8" },
329	        );
330	
331	        if (fastPush.status !== 0) {
332	          emit({
333	            type: "workspace_pr_merge_failed",
334	            task_id: taskId,
335	            feature_id: featureId,
336	            reason: "push_failed_for_done_task",
337	            details: fastPush.stderr ?? "",
338	          });
339	          continue;
340	        }
341	
342	        const fastCoords = parsePrUrl(liveTask.workspace_pr.url);
343	        if (!fastCoords) {
344	          emit({
345	            type: "workspace_pr_merge_failed",
346	            task_id: taskId,
347	            feature_id: featureId,
348	            details: `Cannot parse workspace_pr.url: ${liveTask.workspace_pr.url}`,
349	          });
350	          continue;
351	        }
352	
353	        const fastMergeabilityChecker = opts.checkMergeability ?? fetchPrMergeability;
354	        const fastMergeability = fastMergeabilityChecker(
355	          mgmtRepoOwner,
356	          mgmtRepoName,
357	          fastCoords.pullNumber,
358	          githubToken,
359	        );
