399	      continue;
400	    }
401	
402	    // ── 2. Checkout and sync feature branch ───────────────────────────────────
403	    // Abort any rebase left over from a prior failed cycle before attempting a
404	    // new one. Without this, `git pull --rebase` immediately fails with "rebase-
