406	    // causing every subsequent cycle to fail the same way.
407	    spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
408	
409	    let branchWasRecreated = false;
410	    // Check whether the branch exists on origin, then fetch and sync it.
411	    // A missing branch means it was auto-deleted after a manual workspace-PR
412	    // squash-merge while the PR-poll was suspended (skipPrPoll guard).
413	    // In that case we recreate the branch from mgmtBaseBranch so we can still
414	    // write the done state and close out the task.
415	    try {
416	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
417	
418	      let branchFound = true;
419	      try {
420	        execSync(
421	          `git -C "${workspaceRoot}" ls-remote --exit-code --heads origin "${taskBranch}"`,
422	          { env, stdio: "pipe" },
423	        );
424	      } catch {
425	        branchFound = false;
426	      }
427	
428	      if (!branchFound) {
429	        execSync(
430	          `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${mgmtBaseBranch}"`,
431	          { env, stdio: "pipe" },
432	        );
433	        branchWasRecreated = true;
434	        emit({
435	          type: "pr_merge_branch_recreated",
436	          task_id: taskId,
437	          feature_id: featureId,
438	          base: mgmtBaseBranch,
439	          note: "branch was deleted after manual workspace-PR squash-merge — recreated from base branch",
440	        });
441	      } else {
442	        execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
443	        execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, { env, stdio: "pipe" });
444	      }
445	    } catch (e) {
446	      // Clean up any rebase state left by this attempt before continuing.
447	      spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
448	      emit({
449	        type: "pr_merge_done_blocked",
450	        task_id: taskId,
451	        feature_id: featureId,
452	        reason: "branch_sync_failed",
453	        details: String(e),
454	      });
455	      continue;
456	    }
457	
458	    // ── 3. Update task YAML on disk ───────────────────────────────────────────
459	    const now = new Date().toISOString();
460	    let task: Task;
461	    try {
462	      task = parseYaml(
463	        readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
464	      ) as Task;
465	    } catch (e) {
466	      emit({
467	        type: "pr_merge_done_blocked",
468	        task_id: taskId,
469	        feature_id: featureId,
470	        reason: "task_yaml_read_failed",
471	        details: String(e),
472	      });
473	      continue;
474	    }
475	
476	    // Second idempotency check after checkout (guards against races).
477	    if (task.status !== "in_review") {
478	      emit({
479	        type: "pr_merge_skip",
480	        task_id: taskId,
481	        feature_id: featureId,
482	        reason: `task_already_${task.status}_after_checkout`,
483	      });
484	      continue;
485	    }
486	
487	    task.status = "done";
488	    task.pr = { ...task.pr, status: "merged" };
489	    // If the branch was recreated because the workspace PR was already squash-merged
