491	    // workspacePrRecoveries loop from repeatedly retrying an already-merged PR.
492	    if (branchWasRecreated && task.workspace_pr?.url) {
493	      task.workspace_pr = { ...task.workspace_pr, status: "merged" };
494	    }
495	    task.execution.last_updated_by = gitAuthorEmail;
496	    task.execution.last_updated_at = now;
497	    task.log.push({
498	      action: "done",
499	      by: gitAuthorEmail,
500	      at: now,
501	      note: branchWasRecreated
502	        ? "Implementation PR merged — automated close-out after orphaned-branch recovery."
503	        : "Implementation PR merged — automated close-out by pr-merge loop.",
504	    });
505	
506	    writeFileSync(
507	      taskYamlAbsPath(workspaceRoot, featureId, taskId),
508	      yamlStringify(task),
509	      "utf-8",
510	    );
511	
512	    // ── 4. Auto-ready rule: activate sibling tasks whose deps are now satisfied
513	    const allRelPaths: string[] = [relPath];
514	    const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
515	
516	    let siblingFiles: string[] = [];
517	    try {
518	      siblingFiles = readdirSync(tasksDir).filter(
519	        (f) => /^T\d+\.yaml$/.test(f) && f !== `${taskId}.yaml`,
520	      );
521	    } catch { /* best-effort — skip auto-ready if tasks dir unreadable */ }
522	
523	    // Build a status map for dependency resolution.
524	    // Start with the just-completed task (now done).
525	    // Read sibling statuses from origin/<mgmtBaseBranch> rather than from the
526	    // current feature branch checkout — sibling tasks are marked done on their
527	    // own branches and merged to main, so the feature branch may have a stale
528	    // view (e.g. T3 shows "ready" on T2's branch even though T3 is done on main).
529	    const taskStatusMap = new Map<string, string>([[taskId, "done"]]);
530	    for (const sibFile of siblingFiles) {
531	      try {
532	        const sibRelPath = taskYamlRelPath(featureId, sibFile.replace(/\.yaml$/, ""));
533	        const raw = execSync(
534	          `git -C "${workspaceRoot}" show origin/${mgmtBaseBranch}:${sibRelPath}`,
535	          { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
536	        );
537	        const sibTask = parseYaml(raw) as Task;
538	        taskStatusMap.set(sibTask.id, sibTask.status);
539	      } catch { /* skip — sibling not on main yet, treat as non-done */ }
540	    }
541	
542	    for (const sibFile of siblingFiles) {
543	      try {
544	        const sibPath = join(tasksDir, sibFile);
545	        const sibTask = parseYaml(readFileSync(sibPath, "utf-8")) as Task;
546	
547	        // Only consider todo tasks that depend on the just-completed task.
548	        if (sibTask.status !== "todo") continue;
549	        if (!Array.isArray(sibTask.depends_on) || !sibTask.depends_on.includes(taskId)) continue;
550	
551	        // All deps must now be done.
552	        const allDepsDone = sibTask.depends_on.every(
553	          (depId) => taskStatusMap.get(depId) === "done",
554	        );
555	        if (!allDepsDone) continue;
556	
557	        const sibNow = new Date().toISOString();
558	        sibTask.status = "ready";
559	        sibTask.log.push({
560	          action: "ready",
561	          by: gitAuthorEmail,
562	          at: sibNow,
563	          note: `Task activated — dependency ${taskId} merged and marked done.`,
564	        });
565	
566	        writeFileSync(sibPath, yamlStringify(sibTask), "utf-8");
567	        allRelPaths.push(taskYamlRelPath(featureId, sibTask.id));
568	
569	        emit({
570	          type: "task_auto_readied",
571	          task_id: sibTask.id,
572	          feature_id: featureId,
573	          activated_by: taskId,
574	        });
575	      } catch { /* skip individual sibling errors */ }
576	    }
577	
578	    // ── 5. Commit + push with rebase-and-resolve on rejection ─────────────────
579	    let pushSucceeded = false;
580	
581	    try {
582	      for (const rp of allRelPaths) {
583	        execSync(`git -C "${workspaceRoot}" add "${rp}"`, { env, stdio: "pipe" });
584	      }
585	      execSync(
586	        `git -C "${workspaceRoot}" commit -m "chore(${taskId}): mark done + activate unblocked tasks"`,
587	        { env, stdio: "pipe" },
588	      );
589	    } catch (e) {
590	      emit({
591	        type: "pr_merge_done_blocked",
592	        task_id: taskId,
593	        feature_id: featureId,
594	        reason: "commit_failed",
595	        details: String(e),
596	      });
597	      continue;
598	    }
599	
600	    const firstPush = spawnSync(
601	      "git",
602	      ["-C", workspaceRoot, "push", "origin", taskBranch],
603	      { env, encoding: "utf-8" },
604	    );
605	
606	    if (firstPush.status === 0) {
607	      pushSucceeded = true;
608	    } else {
609	      // Push rejected — attempt fetch + rebase recovery.
610	      try {
611	        execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
612	      } catch (e) {
613	        emit({
614	          type: "pr_merge_done_blocked",
615	          task_id: taskId,
616	          feature_id: featureId,
617	          reason: "fetch_failed_during_push_recovery",
618	          details: String(e),
619	        });
620	        continue;
621	      }
622	
623	      const rebaseResult = spawnSync(
624	        "git",
625	        ["-C", workspaceRoot, "rebase", `origin/${taskBranch}`],
626	        { env, encoding: "utf-8" },
627	      );
628	
629	      if (rebaseResult.status === 0) {
630	        // Clean rebase — retry push.
631	        const retryPush = spawnSync(
632	          "git",
633	          ["-C", workspaceRoot, "push", "origin", taskBranch],
634	          { env, encoding: "utf-8" },
635	        );
636	        if (retryPush.status === 0) {
637	          pushSucceeded = true;
638	        } else {
639	          emit({
640	            type: "pr_merge_done_blocked",
641	            task_id: taskId,
642	            feature_id: featureId,
643	            reason: "push_rejected_after_clean_rebase",
644	            details: retryPush.stderr ?? "",
645	          });
646	          continue;
647	        }
648	      } else {
649	        // Conflicted rebase — spawn Claude to resolve YAML conflict markers.
650	        const conflictedFiles = listConflictedFiles(workspaceRoot, env);
651	        const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
652	
653	        let resolveSucceeded = false;
654	        try {
655	          resolveSucceeded = await invoker(prompt, workspaceRoot, env);
656	        } catch { /* fall through to block */ }
657	
658	        if (resolveSucceeded) {
659	          execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
660	          const continueResult = spawnSync(
661	            "git",
662	            ["-C", workspaceRoot, "rebase", "--continue"],
663	            { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
664	          );
665	
666	          if (continueResult.status === 0) {
667	            const finalPush = spawnSync(
668	              "git",
669	              ["-C", workspaceRoot, "push", "origin", taskBranch],
670	              { env, encoding: "utf-8" },
671	            );
672	            if (finalPush.status === 0) {
673	              pushSucceeded = true;
674	            } else {
675	              spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
676	              emit({
677	                type: "pr_merge_done_blocked",
678	                task_id: taskId,
679	                feature_id: featureId,
680	                reason: "push_rejected_after_claude_rebase",
681	                details: finalPush.stderr ?? "",
682	              });
683	              continue;
684	            }
685	          } else {
686	            spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
687	            emit({
688	              type: "pr_merge_done_blocked",
689	              task_id: taskId,
690	              feature_id: featureId,
691	              reason: "rebase_continue_failed_after_claude_resolve",
692	              details: continueResult.stderr ?? "",
693	            });
694	            continue;
695	          }
696	        } else {
697	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
698	          emit({
699	            type: "pr_merge_done_blocked",
700	            task_id: taskId,
701	            feature_id: featureId,
702	            reason: "rebase_conflict_unresolvable",
703	            conflicted_files: conflictedFiles,
704	          });
705	          continue;
706	        }
707	      }
708	    }
709	
710	    if (!pushSucceeded) continue;
711	
712	    emit({ type: "task_marked_done", task_id: taskId, feature_id: featureId });
713	
714	    // ── 6. Merge the workspace PR via GitHub REST API ─────────────────────────
715	    if (!task.workspace_pr?.url) {
716	      emit({
717	        type: "workspace_pr_missing_for_merge",
718	        task_id: taskId,
719	        feature_id: featureId,
720	        note: "workspace_pr is null — skipping workspace PR merge. Task YAML still marked done.",
721	      });
722	      continue;
723	    }
724	
725	    // When the branch was recreated the workspace PR was already squash-merged
726	    // and auto-deleted. Skip the merge attempt — it would fail anyway, and the
727	    // workspace_pr.status has already been set to "merged" above.
728	    if (branchWasRecreated) {
729	      emit({
730	        type: "workspace_pr_already_merged",
731	        task_id: taskId,
732	        feature_id: featureId,
733	        workspace_pr_url: task.workspace_pr.url,
734	        note: "workspace PR was manually merged before orchestrator could process impl PR merge — skipping redundant merge call",
735	      });
736	      continue;
737	    }
738	
739	    // ── 6a. Rebase feature branch onto latest main before merging ─────────────
740	    try {
741	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
742	    } catch { /* best-effort — proceed with cached origin refs */ }
743	
744	    const rebaseBeforeMerge = spawnSync(
745	      "git",
746	      ["-C", workspaceRoot, "rebase", `origin/${mgmtBaseBranch}`],
747	      { env, encoding: "utf-8" },
748	    );
749	
750	    if (rebaseBeforeMerge.status !== 0) {
751	      const conflictedFiles = listConflictedFiles(workspaceRoot, env);
752	      const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
753	      let resolveSucceeded = false;
754	      try {
755	        resolveSucceeded = await invoker(prompt, workspaceRoot, env);
756	      } catch { /* fall through */ }
757	
758	      if (resolveSucceeded) {
759	        execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
760	        const continueResult = spawnSync(
761	          "git",
762	          ["-C", workspaceRoot, "rebase", "--continue"],
763	          { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
764	        );
765	        if (continueResult.status !== 0) {
766	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
767	          emit({
768	            type: "workspace_pr_rebase_failed",
769	            task_id: taskId,
770	            feature_id: featureId,
771	            reason: "rebase_conflict_before_merge",
772	            conflicted_files: conflictedFiles,
773	            details: continueResult.stderr ?? "",
774	          });
775	          continue;
776	        }
777	      } else {
778	        spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
779	        emit({
780	          type: "workspace_pr_rebase_failed",
781	          task_id: taskId,
782	          feature_id: featureId,
783	          reason: "rebase_conflict_before_merge",
784	          conflicted_files: conflictedFiles,
785	          details: rebaseBeforeMerge.stderr ?? "",
786	        });
787	        continue;
788	      }
789	    }
790	
791	    const rebasePush = spawnSync(
792	      "git",
793	      ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
794	      { env, encoding: "utf-8" },
795	    );
796	
797	    if (rebasePush.status !== 0) {
798	      emit({
799	        type: "workspace_pr_rebase_push_failed",
800	        task_id: taskId,
801	        feature_id: featureId,
802	        details: rebasePush.stderr ?? "",
803	      });
804	      continue;
805	    }
806	
807	    const coords = parsePrUrl(task.workspace_pr.url);
808	    if (!coords) {
809	      emit({
810	        type: "workspace_pr_merge_failed",
811	        task_id: taskId,
812	        feature_id: featureId,
813	        details: `Cannot parse workspace_pr.url: ${task.workspace_pr.url}`,
814	      });
815	      continue;
816	    }
817	
818	    // ── 6b. Mergeability guard — skip merge if PR has conflicts ───────────────
819	    const mergeabilityChecker = opts.checkMergeability ?? fetchPrMergeability;
820	    const mergeability = mergeabilityChecker(mgmtRepoOwner, mgmtRepoName, coords.pullNumber, githubToken);
821	    if (mergeability === false) {
822	      emit({
823	        type: "workspace_pr_not_mergeable",
824	        task_id: taskId,
825	        feature_id: featureId,
826	        workspace_pr_url: task.workspace_pr.url,
827	        note: "PR is CONFLICTING — resolve conflicts on the feature branch before retrying.",
828	      });
829	      continue;
830	    }
831	
832	    const mergeApiResult = mergeWorkspacePrViaApi(
833	      mgmtRepoOwner,
834	      mgmtRepoName,
835	      coords.pullNumber,
836	      githubToken,
837	    );
838	
839	    if (mergeApiResult.success) {
840	      emit({ type: "workspace_pr_merged", task_id: taskId, feature_id: featureId });
841	    } else {
842	      emit({
843	        type: "workspace_pr_merge_failed",
844	        task_id: taskId,
845	        feature_id: featureId,
846	        details: mergeApiResult.details,
847	      });
848	    }
849	  }
850	}
851	
852	// ── Workspace PR recovery ─────────────────────────────────────────────────────
853	
854	export interface HandleWorkspacePrRecoveriesOptions {
855	  recoveries: WorkspacePrRecovery[];
856	  mgmtRepoOwner: string;
857	  mgmtRepoName: string;
858	  /** Base branch of the management repo (default: "main"). Used for rebase-before-merge. */
859	  mgmtBaseBranch?: string;
860	  githubToken: string;
861	  gitAuthorEmail: string;
862	  gitAuthorName?: string;
863	  sshKeyPath?: string;
864	  emit: (event: Record<string, unknown>) => void;
865	  invokeClaudeForResolution?: (
866	    prompt: string,
867	    cwd: string,
868	    env: NodeJS.ProcessEnv,
869	  ) => Promise<boolean>;
870	  /**
871	   * Optional override for checking whether the workspace PR is mergeable.
872	   * Returns true (mergeable), false (conflicting — skip merge), or null (unknown — proceed).
873	   * Defaults to querying the GitHub REST API.
874	   */
875	  checkMergeability?: (
876	    owner: string,
877	    repo: string,
878	    pullNumber: number,
879	    githubToken: string,
880	  ) => boolean | null;
881	}
882	
883	/**
884	 * For each done task whose workspace PR was not merged (detected by the poll loop),
885	 * retry the merge via the GitHub REST API.
886	 *
887	 * Idempotent: if the PR is already merged, GitHub returns a non-success response
888	 * which is logged as a warning rather than an error.
889	 */
890	export async function handleWorkspacePrRecoveries(
891	  opts: HandleWorkspacePrRecoveriesOptions,
892	): Promise<void> {
893	  const { recoveries, mgmtRepoOwner, mgmtRepoName, mgmtBaseBranch = "main", githubToken, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;
894	  const invoker = opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
895	
896	  for (const recovery of recoveries) {
897	    const { taskId, featureId, workspaceRoot, workspacePrUrl } = recovery;
898	    const taskBranch = taskBranchName(featureId, taskId);
899	
900	    const coords = parsePrUrl(workspacePrUrl);
901	    if (!coords) {
902	      emit({
903	        type: "workspace_pr_recovery_error",
904	        task_id: taskId,
905	        feature_id: featureId,
906	        details: `Cannot parse workspace_pr URL: ${workspacePrUrl}`,
907	      });
908	      continue;
909	    }
910	
911	    emit({
912	      type: "workspace_pr_recovery_merging",
913	      task_id: taskId,
914	      feature_id: featureId,
915	      workspace_pr_url: workspacePrUrl,
916	    });
917	
918	    // Rebase onto latest main before merging.
919	    const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName ?? gitAuthorEmail });
920	
921	    try {
922	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
923	    } catch { /* best-effort */ }
924	
925	    try {
926	      execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
927	    } catch (e) {
928	      emit({
929	        type: "workspace_pr_recovery_rebase_failed",
930	        task_id: taskId,
931	        feature_id: featureId,
932	        details: `Failed to checkout task branch: ${String(e)}`,
933	      });
934	      continue;
935	    }
936	
937	    const rebaseResult = spawnSync(
938	      "git",
939	      ["-C", workspaceRoot, "rebase", `origin/${mgmtBaseBranch}`],
940	      { env, encoding: "utf-8" },
941	    );
942	
943	    if (rebaseResult.status !== 0) {
944	      const conflictedFiles = listConflictedFiles(workspaceRoot, env);
945	      const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
946	      let resolveSucceeded = false;
947	      try {
948	        resolveSucceeded = await invoker(prompt, workspaceRoot, env);
949	      } catch { /* fall through */ }
950	
951	      if (resolveSucceeded) {
952	        execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
953	        const continueResult = spawnSync(
954	          "git",
955	          ["-C", workspaceRoot, "rebase", "--continue"],
956	          { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
957	        );
958	        if (continueResult.status !== 0) {
959	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
960	          emit({
961	            type: "workspace_pr_recovery_rebase_failed",
962	            task_id: taskId,
963	            feature_id: featureId,
964	            conflicted_files: conflictedFiles,
965	            details: continueResult.stderr ?? "",
966	          });
967	          continue;
968	        }
969	      } else {
970	        spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
971	        emit({
972	          type: "workspace_pr_recovery_rebase_failed",
973	          task_id: taskId,
974	          feature_id: featureId,
975	          conflicted_files: conflictedFiles,
976	          details: rebaseResult.stderr ?? "",
977	        });
978	        continue;
979	      }
980	    }
981	
982	    const pushResult = spawnSync(
983	      "git",
984	      ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
985	      { env, encoding: "utf-8" },
986	    );
987	
988	    if (pushResult.status !== 0) {
989	      emit({
990	        type: "workspace_pr_recovery_rebase_push_failed",
991	        task_id: taskId,
992	        feature_id: featureId,
993	        details: pushResult.stderr ?? "",
994	      });
995	      continue;
996	    }
997	
998	    // Mergeability guard — skip merge if PR has conflicts.
999	    const recoveryChecker = opts.checkMergeability ?? fetchPrMergeability;
1000	    const recoveryMergeability = recoveryChecker(mgmtRepoOwner, mgmtRepoName, coords.pullNumber, githubToken);
1001	    if (recoveryMergeability === false) {
1002	      emit({
1003	        type: "workspace_pr_not_mergeable",
1004	        task_id: taskId,
1005	        feature_id: featureId,
1006	        workspace_pr_url: workspacePrUrl,
1007	        note: "PR is CONFLICTING — resolve conflicts on the feature branch before retrying.",
1008	      });
1009	      continue;
1010	    }
1011	
1012	    const result = mergeWorkspacePrViaApi(
1013	      mgmtRepoOwner,
1014	      mgmtRepoName,
1015	      coords.pullNumber,
1016	      githubToken,
1017	    );
1018	
1019	    if (result.success) {
1020	      emit({ type: "workspace_pr_recovery_merged", task_id: taskId, feature_id: featureId });
1021	    } else {
1022	      emit({
1023	        type: "workspace_pr_recovery_failed",
1024	        task_id: taskId,
1025	        feature_id: featureId,
1026	        details: result.details,
1027	      });
1028	    }
1029	  }
1030	}
