describe("handleMergedPrs — auto-ready rule", () => {
  it("activates a sibling task from todo to ready when its only dep is completed", async () => {
    const completingTask = makeTask({ id: "T1", status: "in_review", depends_on: [] });
    const siblingTask: Task = {
      id: "T2",
      title: "Sibling Task",
      repo: "impl-repo",
      status: "todo",
      depends_on: ["T1"],
      blocked_reason: null,
      blocked_context: null,
      branch: `feature/${FEATURE_ID}-T2`,
      execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
      pr: { url: "", status: "not_created" },
      workspace_pr: null,
      log: [],
    };

    const wsRoot = makeWorkspaceWithTask(completingTask);
    const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
    writeFileSync(join(tasksDir, "T2.yaml"), yamlStringify(siblingTask), "utf-8");

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(completingTask))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git rebase origin/main
      .mockReturnValueOnce(mockPushSuccess())        // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, taskId: "T1" })],
      emit: (e) => events.push(e),
    }));

    // Sibling task YAML should be updated to ready.
    const updatedSibling = parseYaml(
      readFileSync(join(tasksDir, "T2.yaml"), "utf-8"),
    ) as Task;
    expect(updatedSibling.status).toBe("ready");
    expect(updatedSibling.log.some((e) => e.action === "ready")).toBe(true);
    const readyEntry = updatedSibling.log.find((e) => e.action === "ready");
    expect(readyEntry?.note).toContain("T1");

    // auto-readied event emitted.
    expect(events.some((e) => e.type === "task_auto_readied" && e.task_id === "T2")).toBe(true);
  });

  it("does not activate sibling when it has multiple deps and one is not done", async () => {
    const completingTask = makeTask({ id: "T1", status: "in_review", depends_on: [] });
    const t3Task: Task = {
      id: "T3",
      title: "T3 Task",
      repo: "impl-repo",
      status: "todo",
      depends_on: ["T1"],
      blocked_reason: null,
      blocked_context: null,
      branch: `feature/${FEATURE_ID}-T3`,
