      pr: { url: "", status: "not_created" },
      workspace_pr: null,
      log: [],
    };
    // T4 depends on BOTH T1 and T2; T2 is still todo.
    const t4Task: Task = {
      id: "T4",
      title: "T4 Task",
      repo: "impl-repo",
      status: "todo",
      depends_on: ["T1", "T2"],
      blocked_reason: null,
      blocked_context: null,
      branch: `feature/${FEATURE_ID}-T4`,
      execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
      pr: { url: "", status: "not_created" },
      workspace_pr: null,
      log: [],
    };
    const t2Task: Task = {
      ...t3Task,
      id: "T2",
      depends_on: [],
      status: "todo",
      branch: `feature/${FEATURE_ID}-T2`,
    };

    const wsRoot = makeWorkspaceWithTask(completingTask);
    const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
    writeFileSync(join(tasksDir, "T2.yaml"), yamlStringify(t2Task), "utf-8");
    writeFileSync(join(tasksDir, "T3.yaml"), yamlStringify(t3Task), "utf-8");
    writeFileSync(join(tasksDir, "T4.yaml"), yamlStringify(t4Task), "utf-8");

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(completingTask))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git rebase origin/main
      .mockReturnValueOnce(mockPushSuccess())        // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, taskId: "T1" })],
    }));

    // T3 (depends only on T1) should be activated.
    const t3Updated = parseYaml(readFileSync(join(tasksDir, "T3.yaml"), "utf-8")) as Task;
    expect(t3Updated.status).toBe("ready");

    // T4 (depends on T1 and T2, T2 still todo) should NOT be activated.
    const t4Updated = parseYaml(readFileSync(join(tasksDir, "T4.yaml"), "utf-8")) as Task;
    expect(t4Updated.status).toBe("todo");
  });

  it("activates sibling with multiple deps when all are done on origin/main even if stale on feature branch", async () => {
    // Reproduces the bug where T2 shows as "ready" on T1's feature branch but
    // is actually "done" on origin/main (merged by its own pr-merge loop run).
    const completingTask = makeTask({ id: "T1", status: "in_review", depends_on: [] });
    // T2 is stale on this branch (shows "ready"), but done on origin/main.
    const t2StaleOnBranch: Task = {
      id: "T2",
      title: "T2 Task",
      repo: "impl-repo",
      status: "ready",
      depends_on: [],
      blocked_reason: null,
      blocked_context: null,
      branch: `feature/${FEATURE_ID}-T2`,
      execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
      pr: { url: "", status: "not_created" },
      workspace_pr: null,
      log: [],
    };
    const t2DoneOnMain: Task = { ...t2StaleOnBranch, status: "done" };
    // T4 depends on both T1 (just completing) and T2 (done on main).
    const t4Task: Task = {
      id: "T4",
      title: "T4 Task",
      repo: "impl-repo",
      status: "todo",
      depends_on: ["T1", "T2"],
      blocked_reason: null,
      blocked_context: null,
