      workspace_pr: null,
      log: [],
    };

    const wsRoot = makeWorkspaceWithTask(completingTask);
    const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
    writeFileSync(join(tasksDir, "T2.yaml"), yamlStringify(t2StaleOnBranch), "utf-8");
    writeFileSync(join(tasksDir, "T4.yaml"), yamlStringify(t4Task), "utf-8");

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(completingTask))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git rebase origin/main
      .mockReturnValueOnce(mockPushSuccess())        // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess());

    // execSync: return T2-done YAML when git show is called for T2, undefined otherwise.
    vi.mocked(execSync).mockImplementation((cmd) => {
      if (typeof cmd === "string" && cmd.includes("show origin") && cmd.includes("T2.yaml")) {
        return yamlStringify(t2DoneOnMain) as unknown as Buffer;
      }
      return undefined as unknown as Buffer;
    });

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, taskId: "T1" })],
      emit: (e) => events.push(e),
    }));

    // T4 should be readied — T1 just done, T2 is done on origin/main.
    const t4Updated = parseYaml(readFileSync(join(tasksDir, "T4.yaml"), "utf-8")) as Task;
    expect(t4Updated.status).toBe("ready");
    expect(events.some((e) => e.type === "task_auto_readied" && e.task_id === "T4")).toBe(true);
  });

  it("does not try to activate non-todo siblings", async () => {
    const completingTask = makeTask({ id: "T1", status: "in_review", depends_on: [] });
    const alreadyInProgressSibling: Task = {
      id: "T2",
