// ── 12. handleWorkspacePrRecoveries — rebase before merge ────────────────────

describe("handleWorkspacePrRecoveries", () => {
  const RECOVERY_PR_URL = `https://github.com/${MGMT_OWNER}/${MGMT_REPO}/pull/99`;

