// ── 9. Second idempotency guard (after checkout) ──────────────────────────────

describe("handleMergedPrs — second idempotency guard", () => {
  it("skips when task on disk shows done after checkout (race condition guard)", async () => {
    const liveTask = makeTask({ status: "in_review" });
