  });
});

// ── 10. Rebase before workspace PR merge ─────────────────────────────────────

describe("handleMergedPrs — rebase before workspace PR merge", () => {
  it("emits workspace_pr_rebase_failed and skips merge when rebase conflicts and Claude cannot resolve", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())        // git push (YAML commit)
      .mockReturnValueOnce(mockGitFailed())          // git rebase origin/main — conflict
      .mockReturnValueOnce(mockGitSuccess());        // git rebase --abort (conflict cleanup)

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      invokeClaudeForResolution: async () => false,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_rebase_failed")).toBe(true);
    const rebaseEvent = events.find((e) => e.type === "workspace_pr_rebase_failed");
    expect(rebaseEvent?.reason).toBe("rebase_conflict_before_merge");

    // curl should NOT have been called — merge was skipped.
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);

    // Task YAML on disk should still be done (YAML was committed before the rebase).
    const updatedTask = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;
    expect(updatedTask.status).toBe("done");
  });

  it("resolves rebase conflict with Claude and merges when Claude succeeds", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())        // git push (YAML commit)
      .mockReturnValueOnce(mockGitFailed())          // git rebase origin/main — conflict
      // Claude resolves (injected, no spawnSync)
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --continue
      .mockReturnValueOnce(mockPushSuccess())        // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess())  // workspace PR merge
      .mockReturnValueOnce(mockPushSuccess());       // git push (workspace_pr status write-back)

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      invokeClaudeForResolution: async () => true,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_merged")).toBe(true);
    expect(events.some((e) => e.type === "workspace_pr_rebase_failed")).toBe(false);
  });

  it("emits workspace_pr_rebase_failed when Claude resolves but rebase --continue fails", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())        // git push (YAML commit)
      .mockReturnValueOnce(mockGitFailed())          // git rebase origin/main — conflict
      // Claude resolves (injected)
      .mockReturnValueOnce(mockGitFailed())          // git rebase --continue — fails
      .mockReturnValueOnce(mockGitSuccess());        // git rebase --abort (conflict cleanup)

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      invokeClaudeForResolution: async () => true,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_rebase_failed")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });

  it("emits workspace_pr_rebase_push_failed and skips merge when force-push after rebase fails", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())        // git push (YAML commit)
      .mockReturnValueOnce(mockGitSuccess())         // git rebase origin/main — clean
      .mockReturnValueOnce(mockPushRejected());      // git push --force-with-lease — rejected

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_rebase_push_failed")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });

  it("uses mgmtBaseBranch when rebasing (non-main base)", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git rebase origin/develop
      .mockReturnValueOnce(mockPushSuccess())        // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    await handleMergedPrs(makeBaseOpts(wsRoot, {
      mgmtBaseBranch: "develop",
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
    }));

    // Verify the rebase targeted origin/develop.
    const rebaseCall = vi.mocked(spawnSync).mock.calls.find(
      ([cmd, args]) => cmd === "git" && (args as string[]).includes("rebase") && (args as string[]).some((a) => a.includes("develop")),
    );
    expect(rebaseCall).toBeDefined();
  });
});

// ── 11. Mergeability guard ────────────────────────────────────────────────────

describe("handleMergedPrs — mergeability guard", () => {
  it("emits workspace_pr_not_mergeable and skips merge when PR is CONFLICTING", async () => {
    const task = makeTask();
