  });

  it("emits workspace_pr_recovery_rebase_failed when rebase conflicts and Claude cannot resolve", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitFailed("CONFLICT"))  // git rebase origin/main
      .mockReturnValueOnce(mockGitSuccess());           // git rebase --abort
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleWorkspacePrRecoveries(makeRecoveryOpts(makeRecovery(wsRoot), {
      invokeClaudeForResolution: async () => false,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_recovery_rebase_failed")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });

  it("resolves recovery rebase conflict with Claude and merges when Claude succeeds", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitFailed("CONFLICT"))  // git rebase origin/main — conflict
      // Claude resolves (injected)
      .mockReturnValueOnce(mockGitSuccess())            // git rebase --continue
      .mockReturnValueOnce(mockPushSuccess())           // git push --force-with-lease
      .mockReturnValueOnce(mockCurlMergeSuccess());    // curl merge
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleWorkspacePrRecoveries(makeRecoveryOpts(makeRecovery(wsRoot), {
      invokeClaudeForResolution: async () => true,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_recovery_merged")).toBe(true);
    expect(events.some((e) => e.type === "workspace_pr_recovery_rebase_failed")).toBe(false);
  });

  it("emits workspace_pr_recovery_rebase_push_failed when force-push after rebase fails", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitSuccess())   // git rebase origin/main — clean
      .mockReturnValueOnce(mockPushRejected()); // git push --force-with-lease — fails
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleWorkspacePrRecoveries(makeRecoveryOpts(makeRecovery(wsRoot), {
      emit: (e) => events.push(e),
