 *
 * On push rejection attempts a fetch + rebase onto origin/<taskBranch> + retry once.
 * If still failing, emits `workspace_pr_status_write_failed` — non-fatal, since the
 * PR is already merged on GitHub; the stale "open" status would otherwise cause
 * handleWorkspacePrRecoveries to retry the merge on every subsequent cycle.
 */
function writeWorkspacePrMergedStatus(opts: {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  env: NodeJS.ProcessEnv;
  emit: (event: Record<string, unknown>) => void;
}): void {
  const { workspaceRoot, featureId, taskId, taskBranch, env, emit } = opts;
  const relPath = taskYamlRelPath(featureId, taskId);
  const taskPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);

  try {
    const task = parseYaml(readFileSync(taskPath, "utf-8")) as Task;
    task.workspace_pr = { ...(task.workspace_pr ?? { url: "" }), status: "merged" };
    writeFileSync(taskPath, yamlStringify(task), "utf-8");
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): record workspace PR merged"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    emit({
      type: "workspace_pr_status_write_failed",
      task_id: taskId,
      feature_id: featureId,
      details: String(e),
    });
    return;
  }

  const push1 = spawnSync(
    "git",
    ["-C", workspaceRoot, "push", "origin", taskBranch],
    { env, encoding: "utf-8" },
  );
  if (push1.status === 0) return;

  // Push rejected — fetch + rebase onto origin/<taskBranch> + retry once.
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
  } catch { /* best-effort */ }

  const rebase = spawnSync(
    "git",
    ["-C", workspaceRoot, "rebase", `origin/${taskBranch}`],
    { env, encoding: "utf-8" },
  );

  if (rebase.status === 0) {
    const push2 = spawnSync(
      "git",
      ["-C", workspaceRoot, "push", "origin", taskBranch],
      { env, encoding: "utf-8" },
    );
    if (push2.status !== 0) {
      emit({
        type: "workspace_pr_status_write_failed",
        task_id: taskId,
        feature_id: featureId,
        details: push2.stderr ?? "",
      });
    }
  } else {
    spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
    emit({
      type: "workspace_pr_status_write_failed",
      task_id: taskId,
      feature_id: featureId,
      details: rebase.stderr ?? "",
    });
  }
}

